import '@servicenow/sdk/global'
import { Flow, action, trigger, wfa } from '@servicenow/sdk/automation'

/**
 * Test Flow: Flow Logic Condition Datapill Transform
 *
 * This flow tests the PropertyAccessShape.equals() fix for datapill comparison
 * in flow logic conditions. The test verifies that when a datapill path changes
 * on the instance (e.g., from params.trigger.current.user_name to params.trigger.table_name),
 * the transform correctly updates the datapill reference.
 *
 * Test scenario:
 * - Initial: condition contains `params.trigger.current.user_name`
 * - After instance update: condition should contain `params.trigger.table_name`
 *
 */
Flow(
    {
        $id: Now.ID['3ce1a1c5d4874c8dad6ef03f7b50a85f'],
        name: 'User Name Validation Flow',
        description: 'Demonstrates If flow logic with data pill condition',
        runAs: 'system',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['7e7230a8bed140c980fc0e069d7cc061'], annotation: 'Trigger on sys_user creation' },
        {
            table: 'sys_user',
            condition: 'active=true',
            run_on_extended: 'false',
            run_when_setting: 'both',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // Conditional check if user name equals "Saurabh"
        // This condition contains a datapill that should be updated when transformed from instance
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(params.trigger.current.user_name, 'string')}=Saurabh`,
                annotation: 'Check if user name is Saurabh',
                $id: Now.ID['744c4eaeb1ce3250f8774074995d9903'],
            },
            () => {
                wfa.action(
                    action.core.log,
                    { $id: Now.ID['fafd1a17409f48338c1be6351224071d'], annotation: 'Log when name matches' },
                    {
                        log_level: 'info',
                        log_message: `Welcome ${wfa.dataPill(params.trigger.current.user_name, 'string')}!`,
                    }
                )
            }
        )
    }
)
